var i=`0337-madeleines`;var n=`world-0337`;var r=`FR`;var a=`western-europe`;var o=8;var l=70;var s={en:`Madeleines`,ua:`Мадлен`};var u={en:`A traditional France dish made with chicken egg, lemon zest, all-purpose flour, baking powder. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Франція. Основні інгредієнти: куряче яйце, цедра лимона, пшеничне борошно універсальне, розпушувач тіста. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var g=[{en:`Beat the listed ingredients until pale and light; ensure butter and eggs are at room temperature when specified.`,ua:`Збийте зазначені складники до світлої пишної маси; за потреби використовуйте масло та яйця кімнатної температури.`,t:[`creaming-butter-sugar`,`whisking`],m:8,i:[[`chicken-egg`,3,`pcs`],[`white-granulated-sugar`,130,`g`],[`unsalted-butter`,130,`g`],[`lemon-zest`,8,`g`]]},{en:`Gently fold in the remaining dry or wet ingredients just until homogeneous, without deflating the mixture.`,ua:`Обережно вмішайте решту сухих або рідких складників лише до однорідності, не осаджуючи масу.`,t:[`folding-batter`],m:5,i:[[`all-purpose-flour`,185,`g`],[`baking-powder`,6,`g`],[`whole-cow-milk`,35,`ml`]]},{en:`Cool the prepared ingredients promptly, then refrigerate for about 45 minutes until properly chilled.`,ua:`Швидко охолодіть підготовлені складники, потім поставте в холодильник приблизно на 45 хвилин.`,t:[`rapid-chilling`],m:45,i:[]},{en:`Bake in a preheated 180°C oven for about 12 minutes until set, golden and cooked through. Cool on a rack.`,ua:`Випікайте в розігрітій до 180°C духовці приблизно 12 хвилин до рум’яності та повної готовності. Остудіть на решітці.`,t:[`baking`],m:12,i:[]}];var d={slug:i,id:n,country:`FR`,region:a,servings:8,minutes:70,title:s,text:u,steps:g};export{r as country,d as default,n as id,l as minutes,a as region,o as servings,i as slug,g as steps,u as text,s as title};